import{_ as n,a0 as i,w as c,s,ao as d,I as r,x as o,a1 as p,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在Linux命令列下令人驚歎的驚歎號（!） | LCTT x X-CMD","titleTemplate":false,"description":"在Linux命令列下令人驚歎的驚歎號（!） | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux命令列下令人驚歎的驚歎號（!） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux命令列下令人驚歎的驚歎號（!） | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 10 Amazing and Mysterious Uses of Symbol or Operator in Linux Commands","title":"在Linux命令列下令人驚歎的驚歎號（!）","tag":"201506","desc":""},"relativePath":"201506/20150518 10 Amazing and Mysterious Uses of Symbol or Operator in Linux Commands.md","filePath":"[post].md"}'),m={name:"201506/20150518 10 Amazing and Mysterious Uses of Symbol or Operator in Linux Commands.md"};function l(u,e,h,f,x,w){const t=i("Link");return c(),s("div",null,[e[18]||(e[18]=d(`<h1 id="在linux命令列下令人驚歎的驚歎號" tabindex="-1">在Linux命令列下令人驚歎的驚歎號（!） <a class="header-anchor" href="#在linux命令列下令人驚歎的驚歎號" aria-label="Permalink to “在Linux命令列下令人驚歎的驚歎號（!）”">​</a></h1><p><code>&#39;!&#39;</code>符號在Linux中不但可以用作否定符號，還可以用來從歷史命令記錄中取出命令或不加修改的執行之前運行的命令。下面的所有命令都已經在Bash Shell中經過確切地檢驗。儘管我沒有試過，但大多都不能在別的Shell中運行。這裏我們介紹下Linux命令列中符號<code>&#39;!&#39;</code>那驚人和奇妙的用法。</p><h3 id="_1-使用數字從歷史命令列表中找一條命令來執行" tabindex="-1">1. 使用數字從歷史命令列表中找一條命令來執行 <a class="header-anchor" href="#_1-使用數字從歷史命令列表中找一條命令來執行" aria-label="Permalink to “1. 使用數字從歷史命令列表中找一條命令來執行”">​</a></h3><p>您也許沒有意識到您可以從歷史命令列表（之前已經執行的命令集）中找出一條來運行。首先，通過&quot;history&quot;命令查找之前命令的序號。</p><pre><code>$ history
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/history-Command.gif" alt="使用history命令找到最後執行的命令"></p><p><em>使用history命令找到最後執行的命令</em></p><p>現在，只需要使用歷史命令輸出中顯示在該命令前面的數字便可以運行這個命令。例如，運行一個在<code>history</code>輸出中編號是1551的命令。</p><pre><code>$ !1551
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Run-Commands-By-number.gif" alt="使用命令ID來執行最後運行的命令"></p><p><em>使用命令ID來執行最後運行的命令</em></p>`,11)),r("p",null,[e[1]||(e[1]=o("這樣，編號為1551的命令（上面的例子是",-1)),p(t,{href:"http://www.tecmint.com/12-top-command-examples-in-linux/"},{default:a(()=>[...e[0]||(e[0]=[o("top命令",-1)])]),_:1}),e[2]||(e[2]=o("）便運行了。這種通過ID號來執行之前的命令的方式很有用，尤其是在這些命令都很長的情況下。您只需要使用",-1)),e[3]||(e[3]=r("strong",null,"![history命令輸出的序號]",-1)),e[4]||(e[4]=o("便可以調用它。",-1))]),e[19]||(e[19]=d(`<h3 id="_2-運行之前的倒數第二個、第七個命令等" tabindex="-1">2. 運行之前的倒數第二個、第七個命令等 <a class="header-anchor" href="#_2-運行之前的倒數第二個、第七個命令等" aria-label="Permalink to “2. 運行之前的倒數第二個、第七個命令等”">​</a></h3><p>您可以以另一種方式來運行之前執行的命令，通過使用-1代表最後的命令，-2代表倒數第二個命令，-7代表倒數第七個命令等。</p><p>首先使用history命令來獲得執行過的命令的列表。<strong>history命令的執行很有必要</strong>，因為您可以通過它來確保沒有<code>rm command &gt; file</code>或其他會導致危險的命令。接下來執行倒數第六個、第八個、第十個命令。</p><pre><code>$ history
$ !-6
$ !-8
$ !-10
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/3.gif" alt="通過負數序號運行之前執行的命令"></p><p><em>通過負數序號運行之前執行的命令</em></p><h3 id="_3-傳遞最後執行的命令的參數-以方便的運行新的命令" tabindex="-1">3. 傳遞最後執行的命令的參數，以方便的運行新的命令 <a class="header-anchor" href="#_3-傳遞最後執行的命令的參數-以方便的運行新的命令" aria-label="Permalink to “3. 傳遞最後執行的命令的參數，以方便的運行新的命令”">​</a></h3><p>我需要顯示<code>/home/$USER/Binary/firefox</code>文件夾的內容，因此我執行：</p><pre><code>$ ls /home/$USER/Binary/firefox
</code></pre><p>接下來，我意識到我應該執行&#39;ls -l&#39;來查看哪個文件是可執行文件。因此我應該重新輸入整個命令麼？不，我不需要。我僅需要在新的命令中帶上最後的參數，類似：</p><pre><code>$ ls -l !$
</code></pre><p>這裏<code>!$</code>將把最後執行的命令的參數傳遞到這個新的命令中。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/4.gif" alt="將上一個命令的參數傳遞給新命令"></p><p><em>將上一個命令的參數傳遞給新命令</em></p><h3 id="_4-如何使用-來處理兩個或更多的參數" tabindex="-1">4. 如何使用!來處理兩個或更多的參數 <a class="header-anchor" href="#_4-如何使用-來處理兩個或更多的參數" aria-label="Permalink to “4. 如何使用!來處理兩個或更多的參數”">​</a></h3><p>比如説我在桌面創建了一個文本文件file1.txt。</p><pre><code>$ touch /home/avi/Desktop/1.txt
</code></pre><p>然後在cp命令中使用絕對路徑將它拷貝到<code>/home/avi/Downloads</code>。</p><pre><code>$ cp /home/avi/Desktop/1.txt /home/avi/downloads
</code></pre><p>這裏，我們給cp命令傳遞了兩個參數。第一個是<code>/home/avi/Desktop/1.txt</code>，第二個是<code>/home/avi/Downloads</code>。讓我們分別處理他們，使用<code>echo [參數]</code>來打印兩個不同的參數。</p><pre><code>$ echo &quot;1st Argument is : !^&quot;
$ echo &quot;2nd Argument is : !cp:2&quot;
</code></pre><p>注意第一個參數可以使用<code>&quot;!^&quot;</code>進行打印，其餘的命令可以通過<code>&quot;![命令名]:[參數編號]&quot;</code>打印。</p><p>在上面的例子中，第一個命令是<code>cp</code>，第二個參數也需要被打印。因此是<code>&quot;!cp:2&quot;</code>，如果任何命令比如xyz運行時有5個參數，而您需要獲得第四個參數，您可以使用<code>&quot;!xyz:4&quot;</code>。所有的參數都可以通過<code>&quot;!*&quot;</code>來獲得。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/5.gif" alt="處理兩個或更多的參數"></p><p><em>處理兩個或更多的參數</em></p><h3 id="_5-以關鍵字為基礎執行上個的命令" tabindex="-1">5. 以關鍵字為基礎執行上個的命令 <a class="header-anchor" href="#_5-以關鍵字為基礎執行上個的命令" aria-label="Permalink to “5. 以關鍵字為基礎執行上個的命令”">​</a></h3><p>我們可以以關鍵字為基礎執行上次執行的命令。可以從下面的例子中理解：</p><pre><code>$ ls /home &gt; /dev/null						[命令1]
$ ls -l /home/avi/Desktop &gt; /dev/null		                [命令2]	
$ ls -la /home/avi/Downloads &gt; /dev/null	                [命令3]
$ ls -lA /usr/bin &gt; /dev/null				        [命令4]
</code></pre><p>上面我們使用了同樣的命令（ls），但有不同的開關和不同的操作文件夾。而且，我們還將輸出傳遞到<code>/dev/null</code>，我們並未顯示輸出，因而終端依舊很乾淨。</p><p>現在以關鍵字為基礎執行上個的命令。</p><pre><code>$ ! ls					[命令1]
$ ! ls -l				[命令2]	
$ ! ls -la				[命令3]
$ ! ls -lA				[命令4]
</code></pre><p>檢查輸出，您將驚奇發現您僅僅使用關鍵字<code>ls</code>便執行了您已經執行過的命令。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/6.gif" alt="以關鍵字為基礎執行命令"></p><p><em>以關鍵字為基礎執行命令</em></p><p>（LCTT 譯註：澄清一下，這種用法會按照命令名來找到最後匹配的命令，不會匹配參數。所以上述執行的四個命令都是執行了 <code>ls -lA /usr/bin &gt; /dev/null</code>，並增加了新的參數而已。）</p><h3 id="_6-操作符的威力" tabindex="-1">6. !!操作符的威力 <a class="header-anchor" href="#_6-操作符的威力" aria-label="Permalink to “6. !!操作符的威力”">​</a></h3><p>您可以使用<code>(!!)</code>運行/修改您上個運行的命令。它將附帶一些修改/調整並調用上個命令。讓我給您展示一些實際情境。</p><p>昨天我運行了一行腳本來獲得我的私有IP，因此我執行了：</p><pre><code>$ ip addr show | grep inet | grep -v &#39;inet6&#39;| grep -v &#39;127.0.0.1&#39; | awk &#39;{print $2}&#39; | cut -f1 -d/
</code></pre><p>接着，我突然發現我需要將上面腳本的輸出重定向到一個ip.txt的文件，因此，我該怎麼辦呢？我該重新輸入整個命令並重定向到一個文件麼？一個簡單的解決方案是使用向上光標鍵並添加<code>&#39;&gt; ip.txt&#39;</code>來將輸出重定向到文件。</p><pre><code>$ ip addr show | grep inet | grep -v &#39;inet6&#39;| grep -v &#39;127.0.0.1&#39; | awk &#39;{print $2}&#39; | cut -f1 -d/ &gt; ip.txt
</code></pre><p>在這裏要感謝救世主&quot;向上光標鍵&quot;。現在，考慮下面的情況，這次我運行了下面這一行腳本。</p><pre><code>$ ifconfig | grep &quot;inet addr:&quot; | awk &#39;{print $2}&#39; | grep -v &#39;127.0.0.1&#39; | cut -f2 -d:
</code></pre><p>一旦我運行了這個腳本，Bash提示符便返回了錯誤消息<code>&quot;bash: ifconfig: command not found&quot;</code>。原因並不難猜，我運行了本應以root權限的運行的命令。</p><p>所以，怎麼解決呢？以root用户登錄並且再次鍵入整個命令就太麻煩了！而且向上導航鍵也不管用了（LCTT 譯註：當你以新的用户身份登錄了，是不能用向上光標鍵找到之前的另外一個用户的命令歷史的）。因此，我們需要調用<code>&quot;!!&quot;</code>（去掉引號），它將為那個用户調用上個命令。</p><pre><code>$ su -c !! root
</code></pre><p>這裏su是用來切換到root用户的，<code>-c</code>用來以某用户運行特定的命令，最重要的部分是<code>!!</code>，它將被替換為上次運行的命令。當然！您需要提供root密碼。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/7.gif" alt="!!操作符的威力"></p><p><em>!!操作符的威力</em></p><p>我通常在下面的情景中使用<code>!!</code>。</p><p>當我用普通用户來運行apt-get，我通常收到提示説我沒有權限來執行。</p><pre><code>$ apt-get upgrade &amp;&amp; apt-get dist-upgrade
</code></pre><p>好吧，有錯誤。但別擔心，使用下面的命令來成功的執行...</p><pre><code>$ su -c !!
</code></pre><p>同樣的適用於：</p><pre><code>$ service apache2 start
</code></pre><p>或</p><pre><code>$ /etc/init.d/apache2 start
</code></pre><p>或</p><pre><code>$ systemctl start apache2
</code></pre><p>普通用户不被授權執行那些任務，這樣相當於我運行：</p><pre><code>$ su -c &#39;service apache2 start&#39;
</code></pre><p>或</p><pre><code>$ su -c &#39;/etc/init.d/apache2 start&#39;
</code></pre><p>或</p><pre><code>$ su -c &#39;systemctl start apache2&#39;
</code></pre><p>（LCTT 譯註：使用<code>!!</code>之前，一定要確認你執行的是什麼命令！另外，在 root 身份下，千萬不要養成使用它的習慣，因為你總是會在不合適的目錄執行不合適的命令！）</p><h3 id="_7-運行一個影響所有除了-file-name-的文件命令" tabindex="-1">7.運行一個影響所有除了![FILE_NAME]的文件命令 <a class="header-anchor" href="#_7-運行一個影響所有除了-file-name-的文件命令" aria-label="Permalink to “7.運行一個影響所有除了![FILE_NAME]的文件命令”">​</a></h3><p><code>!</code>（邏輯非）能用來對除了<code>&#39;!&#39;</code>後的文件的所有的文件/擴展名執行命令。</p><p>A.從文件夾移除所有文件，2.txt除外。</p><pre><code>$ rm !(2.txt)
</code></pre><p>B.從文件夾移除所有的文件類型，pdf類型除外。</p><pre><code>$ rm !(*.pdf)
</code></pre><h3 id="_8-檢查某個文件夾-比如-home-avi-tecmint-是否存在-並打印" tabindex="-1">8.檢查某個文件夾（比如/home/avi/Tecmint）是否存在？並打印 <a class="header-anchor" href="#_8-檢查某個文件夾-比如-home-avi-tecmint-是否存在-並打印" aria-label="Permalink to “8.檢查某個文件夾（比如/home/avi/Tecmint）是否存在？並打印”">​</a></h3><p>這裏，我們使用<code>&#39;! -d&#39;</code>來驗證文件夾是否存在，當文件夾不存在時，將使用其後跟隨AND操作符<code>(&amp;&amp;)</code>進行打印，當文件夾存在時，將使用OR操作符<code>(||)</code>進行打印。</p><p>邏輯上，當<code>[ ! -d /home/avi/Tecmint ]</code>的輸出為0時，它將執行AND邏輯符後面的內容，否則，它將執行OR邏輯符<code>(||)</code>後面的內容。</p><pre><code>$ [ ! -d /home/avi/Tecmint ] &amp;&amp; printf &#39;\\nno such /home/avi/Tecmint directory exist\\n&#39; || printf &#39;\\n/home/avi/Tecmint directory exist\\n&#39;
</code></pre><h3 id="_9-檢查某文件夾是否存在-如果不存在則退出該命令" tabindex="-1">9.檢查某文件夾是否存在？如果不存在則退出該命令 <a class="header-anchor" href="#_9-檢查某文件夾是否存在-如果不存在則退出該命令" aria-label="Permalink to “9.檢查某文件夾是否存在？如果不存在則退出該命令”">​</a></h3><p>類似於上面的情況，但這裏當期望的文件夾不存在時，該命令會退出。</p><pre><code>$ [ ! -d /home/avi/Tecmint ] &amp;&amp; exit
</code></pre><h3 id="_10-如果您的home文件夾內不存在一個文件夾-比方説test-則創建它" tabindex="-1">10.如果您的home文件夾內不存在一個文件夾（比方説test），則創建它 <a class="header-anchor" href="#_10-如果您的home文件夾內不存在一個文件夾-比方説test-則創建它" aria-label="Permalink to “10.如果您的home文件夾內不存在一個文件夾（比方説test），則創建它”">​</a></h3><p>這是腳本語言中的一個常用的實現，當期望的文件夾不存在時，創建一個。</p><pre><code>[ ! -d /home/avi/Tecmint ] &amp;&amp; mkdir /home/avi/Tecmint
</code></pre><p>這便是全部了。如果您知道或偶爾遇到其他值得了解的<code>&#39;!&#39;</code>使用方法，請您在反饋的地方給我們提建議。保持聯繫！</p><hr>`,85)),r("p",null,[e[6]||(e[6]=o("via: ",-1)),p(t,{href:"http://www.tecmint.com/mysterious-uses-of-symbol-or-operator-in-linux-commands/"},{default:a(()=>[...e[5]||(e[5]=[o("http://www.tecmint.com/mysterious-uses-of-symbol-or-operator-in-linux-commands/",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=o("作者：",-1)),p(t,{href:"http://www.tecmint.com/author/avishek/"},{default:a(()=>[...e[7]||(e[7]=[o("Avishek Kumar",-1)])]),_:1}),e[11]||(e[11]=o(" 譯者：",-1)),p(t,{href:"https://github.com/wwy-hust"},{default:a(()=>[...e[8]||(e[8]=[o("wwy-hust",-1)])]),_:1}),e[12]||(e[12]=o(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[9]||(e[9]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[15]||(e[15]=o("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[13]||(e[13]=[o("LCTT",-1)])]),_:1}),e[16]||(e[16]=o(" 原創翻譯，",-1)),p(t,{href:"https://linux.cn/"},{default:a(()=>[...e[14]||(e[14]=[o("Linux中國",-1)])]),_:1}),e[17]||(e[17]=o(" 榮譽推出",-1))])])}const _=n(m,[["render",l]]);export{T as __pageData,_ as default};
